export default function HomePage() {
 useEffect(() => {
  const scenes = Array.from(document.querySelectorAll<HTMLElement>('.scene'));
  const tabs = Array.from(document.querySelectorAll<HTMLButtonElement>('[data-scene]'));
  const cleanups: Array<() => void> = [];
  const bind = (button: HTMLButtonElement, handler: () => void) => { button.addEventListener('click',handler); cleanups.push(() => button.removeEventListener('click',handler)); };
  const show = (index: number) => {
   scenes.forEach((el,i) => { el.classList.toggle('active',i===index); el.setAttribute('aria-hidden',String(i!==index)); });
   tabs.forEach((el,i) => { el.classList.toggle('selected',i===index); el.setAttribute('aria-pressed',String(i===index)); });
  };
  tabs.forEach((tab,i) => bind(tab,() => show(i)));
  document.querySelectorAll<HTMLButtonElement>('[data-jump]').forEach(tab => bind(tab,() => show(Number(tab.dataset.jump))));
  const setupGroup = (attribute: string,selector: string) => {
   const buttons = Array.from(document.querySelectorAll<HTMLButtonElement>('['+attribute+']'));
   const panels = Array.from(document.querySelectorAll<HTMLElement>(selector));
   const select = (index: number) => {
    panels.forEach((el,i) => { el.classList.toggle('showing',i===index); el.setAttribute('aria-hidden',String(i!==index)); });
    buttons.forEach((el,i) => el.setAttribute('aria-pressed',String(i===index)));
   };
   buttons.forEach((button,i) => bind(button,() => select(i)));
   select(0);
  };
  setupGroup('data-batch','.product-batch');
  setupGroup('data-equipment','.equipment-batch');
  const photos = Array.from(document.querySelectorAll<HTMLElement>('.company-photo'));
  const photoButtons = Array.from(document.querySelectorAll<HTMLButtonElement>('[data-company]'));
  const selectPhoto = (index: number) => {
   photos.forEach((el,i) => { el.classList.toggle('photo-current',i===index); el.setAttribute('aria-hidden',String(i!==index)); });
   photoButtons.forEach((el,i) => el.setAttribute('aria-pressed',String(i===index)));
   const caption = document.querySelector('.company-visual>span');
   if (caption) caption.textContent = (index===0 ? '외부 전경' : '내부 생산 현장')+'';
  };
  photoButtons.forEach((button,i) => bind(button,() => selectPhoto(i)));
  selectPhoto(0);
  return () => cleanups.forEach(cleanup => cleanup());
 }, []);
 return <div dangerouslySetInnerHTML={{__html:companyMarkup}} />;
}
